async function main() {
  const passwordHash = await bcrypt.hash('PFAStaff@2024!', 10);
  let created = 0, skipped = 0;

  for (const emp of employees) {
    try {
      const existing = await prisma.employee.findUnique({ where: { cnic: emp.cnic } });
      if (existing) { skipped++; continue; }

      await prisma.employee.create({
        data: {
          name: emp.name,
          email: emp.email,
          password: passwordHash,
          role: 'employee',
          cnic: emp.cnic,
          mobilePhone: emp.phone || null,
          department: emp.district || null,
          officeLocation: 'Head Office 83-C, New Muslim Town near Naqsha Stop, Lahore (0800-80500)',
        },
      });
      created++;
    } catch (err) {
      if (err.code === 'P2002') {
        // email conflict — append district to make unique
        try {
          const altEmail = emp.email.replace('@pfa.gov.pk', `_${emp.district.toLowerCase().replace(/\s+/g, '')}@pfa.gov.pk`);
          await prisma.employee.create({
            data: {
              name: emp.name,
              email: altEmail,
              password: passwordHash,
              role: 'employee',
              cnic: emp.cnic,
              mobilePhone: emp.phone || null,
              department: emp.district || null,
              officeLocation: 'Head Office 83-C, New Muslim Town near Naqsha Stop, Lahore (0800-80500)',
            },
          });
          created++;
        } catch (err2) {
          console.error(`Skip (email conflict): ${emp.name} / ${emp.cnic}`, err2.message);
          skipped++;
        }
      } else {
        console.error(`Error inserting ${emp.name} / ${emp.cnic}:`, err.message);
        skipped++;
      }
    }
  }

  console.log(`Done. Created: ${created}, Skipped (already in DB): ${skipped}`);
  await prisma.$disconnect();
}

main().catch(async err => {
  console.error(err);
  await prisma.$disconnect();
  process.exit(1);
});
